using System.Web.Mvc;using FindIt.DAL;namespace FindIt.Controllers{public class AdminController:Controller{ItemRepository items=new ItemRepository();ClaimRepository claims=new ClaimRepository();UserRepository users=new UserRepository();bool A=>Session["Role"] as string=="Admin"&&Session["UserId"]!=null;protected override void OnActionExecuting(System.Web.Mvc.ActionExecutingContext c){if(!A)c.Result=RedirectToAction("Login","Account");base.OnActionExecuting(c);}public ActionResult Index(){return View(items.AdminStats());}public ActionResult Users(){return View(users.All());}[HttpPost,ValidateAntiForgeryToken]public ActionResult ToggleUser(int id,bool active){users.SetActive(id,active);return RedirectToAction("Users");}public ActionResult Items(string q,string type){return View(items.AllAdmin(q,type));}[HttpPost,ValidateAntiForgeryToken]public ActionResult DeleteItem(int id){items.AdminDelete(id);return RedirectToAction("Items");}[HttpPost,ValidateAntiForgeryToken]public ActionResult CloseItem(int id){items.Close(id);return RedirectToAction("Items");}public ActionResult Claims(){return View(claims.All());}[HttpPost,ValidateAntiForgeryToken]public ActionResult Decide(int id,bool approve,string remarks){try{if(!claims.Decide(id,approve,remarks))TempData["Error"]="Claim already processed or item unavailable.";else TempData["Message"]="Claim decision saved.";}catch{TempData["Error"]="Decision failed.";}return RedirectToAction("Claims");}}}